      "category": "Python Basics",
      "isImportant": false,
      "sourceRef": "GTU PDS Syllabus Unit 1",
      "answer": "<strong>Time Complexity:</strong> Python dictionaries are implemented using Hash Tables. Key lookups (<code>d[key]</code>), insertion, and deletion operate in average <strong>$O(1)$ constant time</strong>.<br><br><strong>Dictionary Comprehension:</strong> Constructs dictionaries concisely:<br><code>squares = {x: x**2 for x in range(5)} &rarr; {0: 0, 1: 1, 2: 4, 3: 9, 4: 16}</code>"
