      "category": "Python Basics",
      "isImportant": false,
      "sourceRef": "PDS Unit 1 Notes",
      "answer": "<strong>Control Flow:</strong><ul><li><code>try</code>: Block of code to monitor for exceptions.</li><li><code>except</code>: Executes if a specified error occurs in try block.</li><li><code>else</code>: Executes only if <strong>no</strong> exceptions were raised in the try block.</li><li><code>finally</code>: <strong>Always</strong> executes regardless of whether an exception occurred or was handled (ideal for cleanup: closing database connections and files).</li></ul>"
