      "sourceRef": "Python for Data Science For Dummies",
      "answer": "<strong>Set Characteristics:</strong> Unordered collection of unique, immutable elements backed by a hash table ($O(1)$ membership testing <code>x in s</code>).<br><br><strong>Operations in Data Cleaning:</strong><ul><li><strong>Deduplication:</strong> <code>list(set(raw_list))</code> removes duplicate entries.</li><li><strong>Union (<code>|</code>):</strong> Combines distinct categories from two sources.</li><li><strong>Intersection (<code>&</code>):</strong> Finds overlapping customer IDs between two tables.</li><li><strong>Difference (<code>-</code>):</strong> Identifies missing keys in validation.</li></ul>"
