      "answer": "<strong>Examples:</strong><ul><li><strong><code>enumerate(iterable, start=0)</code>:</strong> Returns an iterator of pairs containing index and value:<br><code>for idx, val in enumerate(['a', 'b']): print(idx, val) &rarr; 0 a, 1 b</code>.</li><li><strong><code>zip(*iterables)</code>:</strong> Combines elements from multiple iterables element-wise into tuples:<br><code>names = ['Alice', 'Bob']; scores = [85, 92]</code><br><code>dict(zip(names, scores)) &rarr; {'Alice': 85, 'Bob': 92}</code>.</li></ul>"
