      "topic": "Garbage Collection",
      "question": "How does Python manage memory and execute Garbage Collection?",
      "category": "Python Internals",
      "isImportant": false,
      "sourceRef": "Tanenbaum & Python Internals",
      "answer": "<strong>Memory Management Mechanisms:</strong><ol><li><strong>Reference Counting:</strong> Primary mechanism. Every object tracks how many references point to it. When count reaches zero, memory is deallocated immediately.</li><li><strong>Generational Cyclical Garbage Collector:</strong> Detects and frees reference cycles (object A references B, and B references A). Operates across 3 generations (Gen 0, 1, 2) based on object survival time.</li></ol>"
