      "answer": "<strong>Comparison:</strong><ul><li><strong>%-formatting (Old):</strong> <code>'Hello %s, score: %d' % (name, score)</code> &rarr; Verbose and error-prone.</li><li><strong><code>str.format()</code> (Python 2.7/3):</strong> <code>'Hello {}, score: {}'.format(name, score)</code> &rarr; Flexible, but wordy.</li><li><strong>F-strings (Python 3.6+ Standard):</strong> <code>f'Hello {name}, score: {score:.2f}'</code> &rarr; Evaluated at runtime directly, cleaner syntax, and significantly faster execution.</li></ul>"
