      "answer": "<strong>Linear Algebra Operations (<code>np.linalg</code>):</strong><ul><li><strong>Matrix Multiplication:</strong> <code>np.dot(A, B)</code> or <code>A @ B</code>.</li><li><strong>Matrix Inverse:</strong> <code>np.linalg.inv(A)</code> (Requires square, non-singular matrix with $\\det(A) \\ne 0$).</li><li><strong>Determinant:</strong> <code>np.linalg.det(A)</code>.</li><li><strong>Eigenvalues & Eigenvectors:</strong> <code>eigenvalues, eigenvectors = np.linalg.eig(A)</code>.</li><li><strong>Transpose:</strong> <code>A.T</code> or <code>np.transpose(A)</code>.</li></ul>"
