      "answer": "<strong>Functions:</strong><ul><li><code>rand(d0, d1)</code>: Uniform distribution over $[0, 1)$.</li><li><code>randn(d0, d1)</code>: Standard Normal (Gaussian) distribution with mean $\\mu = 0$ and variance $\\sigma^2 = 1$.</li><li><code>randint(low, high, size)</code>: Random integers in range $[\\text{low}, \\text{high})$.</li></ul><strong>Why Seed:</strong> <code>np.random.seed(42)</code> sets pseudo-random number generator starting state, ensuring reproducible results across runs."
