      "category": "NumPy",
      "isImportant": true,
      "sourceRef": "Wes McKinney Chapter 4",
      "answer": "<strong>Direct Answer:</strong> <code>np.nan</code> represents IEEE 754 Floating-Point 'Not a Number' (used for missing data); <code>np.inf</code> represents positive infinity (e.g., division by zero).<br><br><strong>Why False:</strong> By IEEE 754 standard definition, NaN is never equal to anything, including another NaN! To check for NaN, you must always use <code>np.isnan(x)</code>."
