      "sourceRef": "GTU PDS QB Q7 & Wes McKinney",
      "answer": "<strong>Fundamental Difference:</strong><ul><li><strong><code>.loc[]</code> (Label-based):</strong> Accesses rows and columns by their textual or declared labels. End slice is <strong>inclusive</strong>!<br>Example: <code>df.loc['Row_A':'Row_C', 'Age']</code></li><li><strong><code>.iloc[]</code> (Integer-position based):</strong> Accesses rows and columns by 0-based integer positional coordinates. End slice is <strong>exclusive</strong>!<br>Example: <code>df.iloc[0:3, 1]</code> (rows 0, 1, 2).</li></ul>"
