      "answer": "<strong>Methods:</strong><ul><li><strong>Detect:</strong> <code>df.duplicated(subset=['email'])</code> returns boolean Series.</li><li><strong>Drop:</strong> <code>df.drop_duplicates(subset=['email'], keep='first', inplace=True)</code> removes redundant records, keeping first occurrence.</li></ul>"
