      "answer": "<strong>Comparison:</strong><ul><li><code>pd.concat([df1, df2], axis=0)</code>: Stacks DataFrames vertically (gluing rows) or horizontally (gluing columns) along an axis by matching index labels.</li><li><code>pd.merge(df1, df2, on='key')</code>: Performs relational database-style joins on common columns (like SQL JOIN).</li><li><code>df1.join(df2)</code>: Specialized merge convenience method for joining on row indexes.</li></ul>"
