      "sourceRef": "GTU PDS Syllabus Unit 5",
      "answer": "<strong>Standard EDA Steps:</strong><ol><li><strong>Data Understanding:</strong> Check shape, column dtypes, head/tail samples, business problem alignment.</li><li><strong>Data Cleaning:</strong> Identify and handle missing values, duplicates, format inconsistencies.</li><li><strong>Univariate Analysis:</strong> Inspect individual variable distributions (histograms, boxplots, summary stats).</li><li><strong>Bivariate & Multivariate Analysis:</strong> Explore feature relationships, correlations, and interactions (scatter plots, heatmaps, pairplots).</li><li><strong>Outlier & Anomaly Detection:</strong> Detect extreme values using IQR / Z-score.</li><li><strong>Feature Engineering Insights:</strong> Identify feature transformations, binning, and encoding opportunities.</li></ol>"
