      "answer": "<strong>Direct Answer:</strong> Financial metrics (income, house prices) often have extreme right-skewed distributions. Log transformation compresses large values while expanding small values, pulling extreme outliers toward the center and making the distribution approximately Gaussian/Normal, which satisfies model assumptions for linear algorithms."
