      "topic": "Collaborating with NGOs & Civil Society",
      "question": "What are the advantages of partnering with an established NGO during the societal internship?",
      "category": "Stakeholders",
      "isImportant": false,
      "sourceRef": "BE05000011 Syllabus",
      "answer": "<strong>Advantages of NGO Partnership:</strong><ul><li><strong>Pre-existing Community Trust:</strong> NGOs have spent years building rapport with residents, lowering skepticism toward student surveyors.</li><li><strong>Domain Expertise:</strong> NGOs have deep contextual understanding of root socio-political and systemic dynamics.</li><li><strong>Logistical Support:</strong> Access to meeting halls, volunteer networks, translation assistance, and safety guidance.</li><li><strong>Sustainable Impact:</strong> The NGO can continue implementing and maintaining the student team's technical recommendations after the semester concludes.</li></ul><strong>Examiner Viva Tip:</strong> If your team worked with an NGO, know the NGO's registered name, founding vision, and supervisor's title."
