      "category": "SDGs Alignment",
      "isImportant": true,
      "sourceRef": "BE05000011 Syllabus",
      "answer": "<strong>SDG 3 Alignment Examples for Computer Engineers:</strong><ul><li><strong>Telemedicine &amp; PHC Booking:</strong> Developing a lightweight web portal or WhatsApp bot for villagers to book appointments at Primary Health Centres (PHCs).</li><li><strong>Vaccination &amp; Maternal Health Reminders:</strong> Automated regional SMS alert system for ASHA workers tracking infant immunization schedules.</li><li><strong>Waterborne Disease Mapping:</strong> GIS dashboard mapping community diarrhea/malaria cases to identify contaminated borewells.</li><li><strong>Mental Health Awareness:</strong> Multilingual educational digital kiosk in regional languages (Gujarati/Hindi) addressing adolescent stress and substance abuse.</li></ul><strong>Examiner Viva Tip:</strong> Target 3.d specifically calls for strengthening early warning, risk reduction, and management of national health risks."
