      "answer": "<strong>SDG 4 Alignment Initiatives:</strong><ul><li><strong>Digital Literacy Modules:</strong> Conducting hands-on workshops for government primary school students teaching foundational computer operations, typing, and safe internet browsing.</li><li><strong>E-Learning Content in Vernacular (Gujarati):</strong> Curating open-source educational videos mapped to the GCERT syllabus for offline playback in rural schools without reliable internet.</li><li><strong>School Resource Auditing:</strong> Creating a digital asset inventory for the school headmaster tracking computer lab health, textbooks, and functional sanitary facilities.</li><li><strong>STEM &amp; Coding Workshops:</strong> Demonstrating visual block coding (Scratch) and basic robotics to ignite scientific curiosity.</li></ul><strong>Examiner Viva Tip:</strong> Target 4.4 focuses on substantially increasing the number of youth with relevant technical skills."
