      "answer": "<strong>SDG 11 Alignment (Sustainable Cities and Communities):</strong><ul><li><strong>Target 11.1 (Adequate Housing &amp; Slum Upgrading):</strong> Documenting living conditions, fire safety, and sanitation access in informal settlements.</li><li><strong>Target 11.2 (Safe, Affordable Public Transport):</strong> Surveying accessibility of Surat BRTS / City Bus connectivity for daily wage migrant laborers.</li><li><strong>Target 11.6 (Air Quality &amp; Municipal Waste):</strong> Low-cost IoT air pollution monitoring around industrial zones (Pandesara/Sachin) and open dumpsites.</li><li><strong>Target 11.b (Disaster Risk Reduction):</strong> Mapping local flood vulnerability zones along the Tapi River basin and identifying safe community shelter buildings.</li></ul><strong>Examiner Viva Tip:</strong> Surat is internationally known for its Smart City initiatives and post-1994 plague public health transformation."
